309	 *
310	 * A head commit normally carries one or two runs, so this only matters when a
311	 * workflow has been re-dispatched several times against the same commit — the case
312	 * where the detail would otherwise grow a line per attempt. Two names the run that is
313	 * presumably the one producing the check, and the count says the rest are there.
314	 */
315	const RUNS_NAMED = 2;
316	
317	/** The unfinished runs on the commit, as one clause a blocker can carry. */
318	function describeActiveRuns(activeRuns: readonly ActiveRun[]): string {
319	  const named = activeRuns.slice(0, RUNS_NAMED).map((run) => `"${run.name}" (${run.status})`);
320	  const rest = activeRuns.length - named.length;
321	  const more = rest > 0 ? `, +${rest} more` : "";
322	  // Said without a verb, so one run and several read alike: `unfinished on this
323	  // commit` is the predicate, and the subject's number does not change it.
324	  return `${named.length === 1 ? "workflow run" : "workflow runs"} ${named.join(", ")}${more}`;
325	}
