327	/**
328	 * Explain a BLOCKED verdict in terms of the required checks, so a refusal names
329	 * the check to fix rather than restating that GitHub said no.
330	 */
331	function explainRequiredChecks(signals: MergeSignals): Blocker[] {
332	  const blockers: Blocker[] = [];
333	  const byName = new Map(signals.checks.map((c) => [c.name, c]));
334	
335	  for (const context of signals.requiredChecks) {
336	    const run = byName.get(context);
337	    if (!run) {
338	      // Absent is two different situations, and the difference is whether a run for
339	      // this commit is in flight. GitHub creates the context when the producing job
340	      // reaches it, so a commit that is being validated right now has its workflow
341	      // run and no check run of that name — reporting `checks-missing` there was
342	      // false when it was reported and dispatched a second run of the same work.
343	      if (signals.activeRuns.length > 0) {
344	        blockers.push({
345	          kind: "checks-pending",
346	          detail:
347	            `required check "${context}" has not registered yet; ${describeActiveRuns(signals.activeRuns)} ` +
348	            "unfinished on this commit, and dispatching CI would duplicate it",
349	        });
350	      } else {
351	        blockers.push({
352	          kind: "checks-missing",
353	          detail: `required check "${context}" has not run on the head commit`,
354	        });
355	      }
356	    } else if (run.status !== "completed") {
357	      blockers.push({
358	        kind: "checks-pending",
359	        detail: `required check "${context}" is ${run.status}`,
360	      });
361	    } else if (!PASSING.has((run.conclusion ?? "").toLowerCase())) {
362	      const where = run.detailsUrl ? ` (${run.detailsUrl})` : "";
363	      blockers.push({
364	        kind: "checks-failing",
365	        detail: `required check "${context}" concluded ${run.conclusion}${where}`,
366	      });
367	    }
368	  }
369	  return blockers;

