/** The marker that turns a pattern into an exclusion. */
const NEGATION = "!";

/**
 * `pattern` split into whether it excludes and the path form it names.
 *
 * Only a LEADING `!` negates. A `!` anywhere else is an ordinary character in a
 * filename, which is what it is.
 */
function splitNegation(pattern: string): { negated: boolean; body: string } {
  return pattern.startsWith(NEGATION)
    ? { negated: true, body: pattern.slice(NEGATION.length) }
    : { negated: false, body: pattern };
}

/** Whether `pattern` claims `file`. A leading `!` is not understood here: see `patternsClaim`. */
export function pathMatches(file: string, pattern: string): boolean {
  return pattern.endsWith("/**") ? file.startsWith(pattern.slice(0, -2)) : file === pattern;
}

/**
 * Whether `patterns` claim `file`, gitignore's way: the last pattern that names it decides,
 * and a file no pattern names is not claimed.
 *
 * The order is the whole semantic. `[".github/**", "!.github/atomaton/skills/**"]` admits a
 * skill file, and the same two patterns the other way round govern it, so a list is read top
 * to bottom and an exclusion can be undone by a later inclusion. That is the one rule
 * everybody already knows from `.gitignore`, and the alternative — take any exclusion as
 * final, wherever it sits — makes the meaning depend on a precedence nobody can see.
 */
export function patternsClaim(file: string, patterns: readonly string[]): boolean {
  let claimed = false;
  for (const pattern of patterns) {
    const { negated, body } = splitNegation(pattern);
    if (pathMatches(file, body)) claimed = !negated;
  }
  return claimed;
}
```

